    loose_status_checks = Dir.glob(Rails.root.join("spec/requests/**/*_spec.rb")).select do |path|
      File.read(path).match?(/\[\s*401\s*,\s*403\s*\]/)
    end
    expect(loose_status_checks).to be_empty
  end
